#!/bin/bash
# #447's second campaign (the post-merge rounds' lanes): after cand2/ (96a8d57ea) builds, the paired validation of main's
# rule (main2/, 53854a7c2) against cand2's on 8 permitted lanes on the 76 units of the deferred-lane-rule-447-2026-11-06
# record, five rounds of two holds; then c-testsuite's 220 programs by both builds' rules, one round; then the grid's 22
# units' resident memory (--rss --cold) by both rules, two rounds. Beside them, cand2's correctness gates in two
# sequences, the release steps and the AddressSanitizer steps.
cd ~/buster-fast-bench/447-claude
until grep -q '^exit=' logs/build-cand2.txt 2>/dev/null; do sleep 10; done
grep -q '^exit=0' logs/build-cand2.txt || exit 1
(scripts/gates-steps.sh cand2 cand2-asan fixtures c-testsuite sqlite musl-1 musl-2 musl-3 musl-4 > logs/gates-cand2-release.out 2>&1 < /dev/null &)
